import { defineConfig, devices } from '@playwright/test';
import { AUTH_FILE } from './tests/setup/paths';

const BASE_URL = process.env.BASE_URL ?? 'http://localhost:4173';
const isCI = !!process.env.CI;


export default defineConfig({
  testDir: './tests',
  fullyParallel: true,
  forbidOnly: isCI,
  retries: isCI ? 2 : 0,
  workers: isCI ? 2 : undefined,
  timeout: 30_000,
  expect: {
    timeout: 7_000,
    toHaveScreenshot: { maxDiffPixelRatio: 0.01, animations: 'disabled' },
  },
  // Baselines are generated by CI on Linux only (official Playwright container).
  snapshotPathTemplate: '{testDir}/visual/__screenshots__/{arg}{ext}',
  reporter: [
    ['list'],
    ['html', { open: 'never', outputFolder: 'playwright-report' }],
    ['json', { outputFile: 'reports/results.json' }],
    ['junit', { outputFile: 'reports/junit.xml' }],
    // Records reports/live-events.jsonl on every run; LIVE=1 also serves the live dashboard (npm run test:live).
    ['./reporters/live-reporter.ts'],
    ...(isCI ? ([['github']] as const) : []),
  ],
  use: {
    baseURL: BASE_URL,
    trace: 'on-first-retry',
    screenshot: 'only-on-failure',
  },
  projects: [
    {
      name: 'setup',
      testMatch: /.*\.setup\.ts/,
      use: { ...devices['Desktop Chrome'] },
    },
    {
      name: 'ui',
      testMatch: 'ui/**/*.spec.ts',
      dependencies: ['setup'],
      use: { ...devices['Desktop Chrome'], storageState: AUTH_FILE },
    },
    {
      name: 'api',
      testMatch: 'api/**/*.spec.ts',
    },
    {
      name: 'visual',
      testMatch: 'visual/**/*.spec.ts',
      use: {
        ...devices['Desktop Chrome'],
        viewport: { width: 1280, height: 800 },
        colorScheme: 'dark',
        contextOptions: { reducedMotion: 'reduce' },
      },
    },
    // Evidence videos (npm run evidence): only when EVIDENCE=1, never in the normal run or CI.
    ...(process.env.EVIDENCE
      ? [{ name: 'evidence', testMatch: 'evidence/**/*.evidence.ts', use: { ...devices['Desktop Chrome'] } }]
      : []),
  ],
  webServer: process.env.BASE_URL
    ? undefined
    : {
        command: 'node server/app.mjs',
        url: `${BASE_URL}/api/health`,
        reuseExistingServer: !isCI,
        timeout: 30_000,
      },
});
